// сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
fn digit_sum(n: i64) -> u32 {
    let n = n.unsigned_abs();
    if n < 10 {
        return n as u32;
    }
    (n % 10) as u32 + digit_sum((n / 10) as i64)
