    }
}

enum Status {
    New,
    Paid(u32),
    Shipped { track: String },
}

fn describe(s: &Status) -> String {
    match s {
        Status::New => "новый".to_string(),
        Status::Paid(sum) => format!("оплачен: {sum} ₽"),
        Status::Shipped { track } => format!("в пути: {track}"),
    }
}

fn main() {
    let a = Point { x: 1, y: 2 };
    let mut b = a.clone();
    b.x = 10;
