#[derive(Debug, PartialEq)]
enum OrderError {
    Format,
    BadQty(String),
    ZeroQty,
}

// "лампа x3" -> ("лампа", 3)
fn parse_order(line: &str) -> Result<(String, u32), OrderError> {
    let (name, qty) = line.split_once(" x").ok_or(OrderError::Format)?;
    let qty = qty.trim();
    let n: u32 = qty.parse().map_err(|_| OrderError::BadQty(qty.to_string()))?;
    if n == 0 {
        return Err(OrderError::ZeroQty);
    }
    Ok((name.trim().to_string(), n))
}

fn main() {
    println!("{:?}", parse_order("лампа x3"));
}

