    check::eq("лампа x3", || parse_order("лампа x3"), Ok(("лампа".to_string(), 3)));
    check::eq("пробелы вокруг", || parse_order("  стол x 12 "), Ok(("стол".to_string(), 12)));
    check::eq("нет количества", || parse_order("лампа"), Err(OrderError::Format));
    check::eq("количество словами", || parse_order("лампа xтри"), Err(OrderError::BadQty("три".to_string())));
    check::eq("ноль", || parse_order("лампа x0"), Err(OrderError::ZeroQty));
